import type { Href } from 'expo-router';

/**
 * The client and reviewer page of a project (app/projectManagement/[id]/review.tsx). A plain path: the typed route
 * list is generated by Metro and only learns about the new screen on its next start.
 */
export function projectReviewHref(projectId: string): Href {
  return `/projectManagement/${encodeURIComponent(projectId)}/review` as Href;
}
